/*
 * pdp_ps5_kernel.cu - the CUDA entry point of the PS-5 kernel.  All of the
 * arithmetic is in pdp_ps5_device.cuh and in the program generated by
 * pdp_ps5_emit from a `pdp-slp/1` file; this file only maps threads to jobs.
 *
 * Build (see build_pdp_ps5.sh):
 *   nvcc -arch=sm_80 -O3 -I<dir of the generated .h/.inc> -DPS5_PARAMS_H='"pdp_ps5_l11.h"' \
 *        -cubin pdp_ps5_kernel.cu
 *
 * Launch with any grid and block; thread t runs jobs t, t + gridDim.x*blockDim.x, ...
 * One job is PS5_TASKS tasks of one row, 32 pairs each (256 pairs).  Inputs,
 * all device pointers:
 *   jobs   2 words per job: row i1, first block
 *   xb, yb transposed base points, PS5_N words per block (bit j of plane i =
 *          bit i of the abscissa/ordinate of base point 32*block + j)
 *   rows   4 u64 per row: xu, yu, xv, yv of U+- = P_i1 +- R
 *   m      number of base points, nblk = ceil(m / 32)
 *   nhits  one counter, zeroed by the host; hits has room for `cap` records
 * If *nhits > cap on return the list overflowed and must be discarded.
 *
 * UNCOMPILED unless build_pdp_ps5.sh reports otherwise; NEVER RUN on a device.
 */
#ifndef PS5_PARAMS_H
#    define PS5_PARAMS_H "pdp_ps5_gen.h"
#endif
#include "pdp_ps5_device.cuh"

extern "C" __global__ void pdp_ps5_run(const ps5_u32 *jobs, ps5_u32 n_jobs, const ps5_u32 *xb,
                                       const ps5_u32 *yb, const ps5_u64 *rows, ps5_u32 m,
                                       ps5_u32 nblk, ps5_u32 *nhits, Ps5Hit *hits, ps5_u32 cap)
{
    const ps5_u32 stride = gridDim.x * blockDim.x;
    for (ps5_u32 job = blockIdx.x * blockDim.x + threadIdx.x; job < n_jobs; job += stride)
        ps5_job(job, jobs, xb, yb, rows, m, nblk, nhits, hits, cap);
}
